const context = options.contextData;
const viewmodel = context.viewmodel;
const topWindow = context.aras.getMostTopWindowWithAras();
const textStyle = context.selectedElement.GetStyleOfRange() || {};
const dialogParameters = {
	oldColor: textStyle.fontcolor || '#404040',
	aras: context.aras,
	type: 'Color'
};
const modelCursor = viewmodel.Cursor();

topWindow.ArasModules.Dialog.show('iframe', dialogParameters).promise.then(color => {
	if (color) {
		const actionsHelper = viewmodel.ActionsHelper();

		actionsHelper.executeAction('arastextactions', {
			actionName: 'fontcolor',
			value: color
		});
	}
});

modelCursor.Set(modelCursor.start, modelCursor.startOffset, modelCursor.end, modelCursor.endOffset);
